30	// Recursively rewrite true -> 1 and false -> 0 (jsonschema._utils.unbool).
31	export function unbool(value) {
32	  if (value === true) return 1;
33	  if (value === false) return 0;
34	  if (Array.isArray(value)) return value.map(unbool);
35	  if (typeof value === 'object' && value !== null) {
36	    const out = {};
37	    for (const [k, v] of Object.entries(value)) out[k] = unbool(v);
38	    return out;
39	  }
40	  return value;
41	}
42	
43	// Deep equality with Python semantics (after unbool-ing both sides).
44	export function deepEqual(one, two) {
45	  return plainEqual(unbool(one), unbool(two));
46	}
