48	function plainEqual(a, b) {
49	  if (a === b) return true;
50	  if (typeof a === 'number' && typeof b === 'number') return a === b;
51	  if (Array.isArray(a) && Array.isArray(b)) {
52	    if (a.length !== b.length) return false;
53	    for (let i = 0; i < a.length; i++) {
54	      if (!plainEqual(a[i], b[i])) return false;
55	    }
56	    return true;
57	  }
58	  if (isPlainObject(a) && isPlainObject(b)) {
59	    const ka = Object.keys(a);
60	    const kb = Object.keys(b);
61	    if (ka.length !== kb.length) return false;
62	    for (const k of ka) {
63	      if (!Object.prototype.hasOwnProperty.call(b, k)) return false;
