// Numeric keywords: multipleOf, maximum, exclusiveMaximum, minimum,
// exclusiveMinimum.
//
// All of these apply only to numbers (booleans are not numbers). Each
// failure yields exactly one error.

import { ValidationError } from '../errors.mjs';

// Python jsonschema chooses the check by whether the divisor literal was a
// float: integer divisors use `instance % dB != 0`, float divisors use
// `int(instance / dB) != instance / dB` (with OverflowError -> failure when
// the quotient overflows to infinity). JS cannot see whether the JSON
// literal had a decimal point, so we use Number.isInteger(divisor), which
// matches on all observable cases: Number.isInteger(Infinity) is false,
// covering the overflow case too.
export function* multipleOf(validator, divisor, instance, schema) {
  if (!validator.isType(instance, 'number')) return;

  let failed;
  if (Number.isInteger(divisor)) {
    failed = instance % divisor !== 0;
  } else {
    failed = !Number.isInteger(instance / divisor);
  }

  if (failed) {
    yield new ValidationError(`${instance} is not a multiple of ${divisor}`);
  }
}

export function* maximum(validator, maximum, instance, schema) {
  if (!validator.isType(instance, 'number')) return;
  if (instance > maximum) {
    yield new ValidationError(`${instance} is greater than the maximum of ${maximum}`);
  }
}

export function* exclusiveMaximum(validator, exclusiveMaximum, instance, schema) {
  if (!validator.isType(instance, 'number')) return;
  if (instance >= exclusiveMaximum) {
    yield new ValidationError(
      `${instance} is greater than or equal to the maximum of ${exclusiveMaximum}`
    );
  }
}

export function* minimum(validator, minimum, instance, schema) {
  if (!validator.isType(instance, 'number')) return;
  if (instance < minimum) {
    yield new ValidationError(`${instance} is less than the minimum of ${minimum}`);
  }
}

export function* exclusiveMinimum(validator, exclusiveMinimum, instance, schema) {
  if (!validator.isType(instance, 'number')) return;
  if (instance <= exclusiveMinimum) {
    yield new ValidationError(
      `${instance} is less than or equal to the minimum of ${exclusiveMinimum}`
    );
  }
}

