// Python jsonschema chooses the check by whether the divisor literal was a
// float: integer divisors use `instance % dB != 0`, float divisors use
// `int(instance / dB) != instance / dB` (with OverflowError -> failure when
// the quotient overflows to infinity). JS cannot see whether the JSON
// literal had a decimal point, so we use Number.isInteger(divisor), which
// matches on all observable cases: Number.isInteger(Infinity) is false,
// covering the overflow case too.
export function* multipleOf(validator, divisor, instance, schema) {
  if (!validator.isType(instance, 'number')) return;

  let failed;
  if (Number.isInteger(divisor)) {
    failed = instance % divisor !== 0;
  } else {
    failed = !Number.isInteger(instance / divisor);
  }

